declare(strict_types=1);
namespace OCA\Mcp\Tests\Unit\Modules\Mail;
use PHPUnit\Framework\TestCase;
final class MailDraftCopyCompositionTest extends TestCase {
    private function parse(array $draft):array {
        $file=dirname(__DIR__,5).'/native/mail-guard/src/Content/DraftCopyComposition.php';
        self::assertFileExists($file,'A protected import must validate exact representability before staging.');require_once $file;
        return \OCA\Mail\Content\DraftCopyComposition::parse($draft);
    }
    private function draft():array {return ['headers'=>['from'=>'Sender <sender@example.test>','to'=>'"Recipient, One" <one@example.test>, two@example.test','cc'=>'copy@example.test','bcc'=>'hidden@example.test','in-reply-to'=>'<parent@example.test>','references'=>'<parent@example.test>'],'subject'=>'Subject','body_plain'=>"plain\n",'body_html'=>'<p>html</p>','draft_flag'=>true,'parts'=>[['part_id'=>'0','parent_id'=>null,'role'=>'container','mime_type'=>'multipart/alternative','content_id'=>null,'disposition'=>null,'filename'=>null],['part_id'=>'1','parent_id'=>'0','role'=>'body','mime_type'=>'text/plain','content_id'=>null,'disposition'=>null,'filename'=>null],['part_id'=>'2','parent_id'=>'0','role'=>'body','mime_type'=>'text/html','content_id'=>null,'disposition'=>null,'filename'=>null]],'attachments'=>[]];}
    public function testExactSupportedCompositionPreservesRecipientsAndBodies():void {$d=$this->draft();$r=$this->parse($d);self::assertSame([['email'=>'one@example.test','name'=>'Recipient, One'],['email'=>'two@example.test','name'=>'']],$r['to']);self::assertSame('hidden@example.test',$r['bcc'][0]['email']);self::assertSame("plain\n",$r['body_plain']);self::assertSame('<parent@example.test>',$r['reply_to']);}
    public function testUnsupportedMetadataAndAmbiguousAddressesRefuseBeforeCopy():void {foreach(['from','to','references','body_cid','related','disposition'] as $case){$d=$this->draft();if($case==='from')$d['headers']['from']='a@example.test, b@example.test';elseif($case==='to')$d['headers']['to']='not-an-address';elseif($case==='references')$d['headers']['references']='<earlier@example.test> <parent@example.test>';elseif($case==='body_cid')$d['parts'][1]['content_id']='body@example.test';elseif($case==='related')$d['parts'][0]['mime_type']='multipart/related';else $d['parts'][0]['disposition']='inline';$refused=false;try{$this->parse($d);}catch(\RuntimeException){$refused=true;}self::assertTrue($refused,$case);}}
    public function testInlineAttachmentIntegrityAndCidMustBeExact():void {$d=$this->draft();$d['parts'][0]['mime_type']='multipart/mixed';$alternative=$d['parts'][0];$alternative['part_id']='1';$alternative['parent_id']='0';$alternative['mime_type']='multipart/alternative';$d['parts'][1]['part_id']='1.1';$d['parts'][1]['parent_id']='1';$d['parts'][2]['part_id']='1.2';$d['parts'][2]['parent_id']='1';array_splice($d['parts'],1,0,[$alternative]);$d['body_html']='<img src="cid:image@example.test">';$d['parts'][]=['part_id'=>'3','parent_id'=>'0','role'=>'attachment','mime_type'=>'image/png','content_id'=>'image@example.test','disposition'=>'inline','filename'=>'image.png'];$a=['part_id'=>'3','mime_type'=>'image/png','filename'=>'image.png','content_id'=>'image@example.test','disposition'=>'inline','charset'=>null,'bytes'=>'synthetic','byte_count'=>9,'sha256'=>hash('sha256','synthetic')];$d['attachments']=[$a];$r=$this->parse($d);self::assertSame($a,$r['attachments'][0]);$d['attachments'][0]['bytes']='changed';$this->expectException(\RuntimeException::class);$this->parse($d);}
    public function testNoncanonicalMixedBodyContainersRefuseInsteadOfChangingMeaning():void {$d=$this->draft();$d['parts'][0]['mime_type']='multipart/mixed';$this->expectException(\RuntimeException::class);$this->parse($d);}
}
